import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAQ: [CaseTemplate] = [bikeRackTheft, keyedCarLot, patioShouting, prankNineOneOne, porchPackages, contractorTools, lakeCrashFatal]

    static let bikeRackTheft = SmallCases.make(
        key: "story.bikeRackTheft",
        category: .property,
        headlines: ["Commuter's $900 Bike Cut From Rack at Transit Stop", "Camera Catches Man With Bolt Cutters at Bike Rack"],
        law: "misdLarceny",
        spec: "Stole a bicycle valued at $900 belonging to {V}, on {DATE}.",
        ages: 18...40,
        victim: true,
        summary: "{V} locked a bicycle to a rack at a transit stop at 8 a.m. on {DATE} and returned at 5 p.m. to a cut lock. A stop camera showed {D} cutting the lock and riding away. {DL} says the bike was abandoned and had no lock on it.",
        state: [E(.video, 3, "Stop Camera", "{D} cuts a cable lock and rides off at 11:40 a.m."), E(.document, 2, "Purchase Receipt", "{V}'s receipt shows a $900 bicycle with a serial number.")],
        defense: [E(.statement, 1, "Abandoned", "{DL} says the bike was unlocked and abandoned.")],
        role: "Bicycle owner",
        exam: [.direct("What did you do on the morning of {DATE}?", "\"I rode to a transit stop and locked my bicycle to the rack at about 8 a.m. before taking a bus to work.\""), .direct("What kind of bike was it?", "\"A $900 bicycle I'd saved up for. I had the receipt with the serial number and I kept it in good condition.\""), .direct("What lock did you use?", "\"A cable lock looped through the frame and the rack. I checked that it clicked shut before I walked away.\""), .direct("What did you find when you came back?", "\"At 5 p.m. the bike was gone and the cut lock was lying on the ground by the rack. I was stunned and called the sheriff's office.\""), .direct("What does the stop's camera show?", "\"At 11:40 a.m., {D} walks up with bolt cutters, cuts the cable, and rides my bike away. The footage is clear.\""), .direct("How long had you owned the bike?", "\"About a year. I rode it to the stop almost every day, and it was my main way of getting to work.\""), .cross("Isn't it true you were not present when it was taken?", "\"Correct. I was at work, so I only know what the camera shows and what I found at 5 p.m.\""), .cross("Did you see anyone near the bike during the week?", "\"I saw it each day and locked it each time. I don't recall anyone paying attention to it before that day.\""), .cross("Was the bike ever left unlocked at the rack?", "\"Not by me. I always locked it. I can't speak to what a neighbor might claim about another bike.\""), .cross("Did {D} take the bike in a hurry?", "\"The camera shows {D} cutting the lock without hesitation and riding off at a normal pace. {D} didn't look around.\""), .cross("Did you recover the bike?", "\"It was recovered a few days later by deputies. It was undamaged, apart from the cut cable.\"")],
        theory: ("{D} cut a lock and took a bike.", "An abandoned bike."),
        allocution: "\"I took what wasn't mine.\"",
        truths: ("{DL} was holding bolt cutters on the video.", "A neighbor said the bike had sat unlocked at the rack for a week."),
        defendant: [.direct("Why did you take the bike?", "\"I thought it was abandoned. It was sitting at the rack, and it looked like it had been there for days with no one using it.\""), .direct("Why did you carry bolt cutters?", "\"I use them for work. I keep them in my bag, and I had them with me when I came through the stop.\""), .direct("What did you do with the cable?", "\"It looked like it was just draped around the frame and the rack, not really secured. I cut it to be sure and took the bike.\""), .direct("Did you see any sign that someone owned it?", "\"No tag, no note, nothing. It was dusty, and I assumed someone had left it there.\""), .direct("Where did you take the bike?", "\"Home. I didn't try to sell it or hide it, and I rode it openly in the daytime.\""), .direct("What did you tell the deputy?", "\"I said I thought it was abandoned and gave it back. I apologized when I understood it belonged to someone.\""), .cross("You cut a lock to take it, didn't you?", "\"I cut a cable. I know that looks bad, and I apologize. I thought it was abandoned.\""), .cross("A bike with a lock on it doesn't look abandoned, does it?", "\"I thought the lock was left behind as well. I should have asked someone before I used the cutters.\""), .cross("You didn't ask anyone at the stop?", "\"No. I didn't see anyone to ask. I should have waited and checked.\""), .cross("You rode off with it in broad daylight?", "\"Yes, at 11:40 in the morning. I wasn't hiding, because I thought I was doing nothing wrong.\""), .cross("The bike was worth $900?", "\"I didn't know that at the time. I thought it was an old bike, and I didn't look at its condition closely.\"")],
        openings: ("At 8 a.m. {V} locked a $900 bicycle to a rack at a transit stop. At 11:40 the stop's camera recorded {D} cutting the cable with bolt cutters and riding away, and {V} came back at 5 p.m. to the cut lock.", "{D} saw a dusty bicycle that appeared abandoned and took it openly in daylight. The defense says {D} believed no one owned it, and the State cannot prove an intent to steal."),
        closings: ("Bolt cutters, a cut lock, a $900 bike, and a camera that watches every second. {D} did not find an abandoned bicycle, because an abandoned bike does not come with a cable lock around the frame.", "{D} cut a loose cable in broad daylight, rode away openly, and handed the bike back as soon as asked. That is the conduct of someone who believed the bicycle was abandoned."),
        timeline: [(0, "8 a.m.: {V} locks the bike."), (0, "11:40 a.m.: {D} cuts the lock."), (0, "5 p.m.: {V} finds the cut lock.")],
        identified: "The transit stop's camera.",
        impact: "It was how I got to work.",
        genders: ["D": .male])

    static let keyedCarLot = SmallCases.make(
        key: "story.keyedCarLot",
        category: .property,
        headlines: ["Car Keyed Along Both Sides in Apartment Lot", "Neighbor Disputes Over Parking Space End With Scratched Paint"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a car, causing damage of $1,300, on {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "{V}'s car was keyed down both sides overnight on {DATE}. The week before, {D} had left a note on the windshield about parking in {D.his} space. A lot camera shows a person in a hooded jacket at the car. {DL} says {D.he} was at home. Damage was put at $1,300.",
        state: [E(.video, 2, "Lot Camera", "A hooded person walks the length of the car at 1:10 a.m."), E(.document, 3, "Note", "'Park elsewhere or else.' signed by {D}.")],
        defense: [E(.statement, 1, "At Home", "{DL} says {D.he} was asleep at home.")],
        role: "Apartment resident",
        exam: [.direct("How did you discover the damage?", "\"At about 7 a.m. on {DATE} I walked out to my car and saw long scratches down both sides. They had been done overnight.\""), .direct("What kind of damage was it?", "\"Deep key scratches along both doors from front to back. The estimate was $1,300 for repainting and repair.\""), .direct("What happened the week before?", "\"I found a note on my windshield from {D}. It said, Park elsewhere or else, and was signed with {D}'s name.\""), .direct("Why did {D} leave that note?", "\"{D} said I was parking in {D.his} space. I parked there once or twice and I didn't think it was assigned.\""), .direct("What does the lot camera show?", "\"At 1:10 a.m. a person in a hooded jacket walks the full length of my car. The picture is dark and grainy.\""), .direct("Whom did you suspect?", "\"{D}, because of the note and the dispute. I told the deputy the next morning about the note and the camera.\""), .cross("Isn't it true you can't see the person's face on the video?", "\"Correct. The hood covers it, and the camera is far from the car, so I can't identify anyone.\""), .cross("Did you see anyone near your car that night?", "\"No. I was asleep and found out in the morning.\""), .cross("Did you see the person hold a key or any tool?", "\"Not clearly. They walk along the car and their arm is close to it, but the image is too dark to see a hand.\""), .cross("Did {D} ever threaten you directly?", "\"Only in the note. We hadn't spoken in person, and I never saw {D} do anything aggressive.\""), .cross("How many other residents have had parking disputes?", "\"I've heard of a few, so there may be other people who were upset about a space.\"")],
        theory: ("{D} keyed a car over a parking spot.", "A grudge with no proof."),
        allocution: "\"I lost my temper.\"",
        truths: ("A key with paint flecks was found in {DL}'s jacket.", "The jacket was a size too small for {DL}."),
        defendant: [.direct("Did you leave the note on {V}'s car?", "\"Yes, I did. I was angry that someone was in my assigned space, and I wrote something harsher than I should have.\""), .direct("What did you mean by or else?", "\"Nothing physical. I meant I'd report the car to the manager. It was a poor choice of words and I regret that.\""), .direct("Where were you at 1:10 a.m. that night?", "\"At home asleep. I work early in the morning, so I'm usually in bed by ten.\""), .direct("Did you scratch {V}'s car?", "\"No. I would never damage someone's car over a parking space. That would cost me far more than it was worth.\""), .direct("Do you own a hooded jacket?", "\"I own one, but it's a size too small for me and I rarely wear it. It's one of those hand-me-downs.\""), .direct("What did you tell the deputy?", "\"That I'd left the note and had nothing to do with the damage. I let the deputy look at my jacket and my keys.\""), .cross("The note said, or else, correct?", "\"Yes. It's a threat in how it reads, and I know why {V} thought of me.\""), .cross("You were angry about the parking space?", "\"I was. I'd paid for that space and it was blocked more than once.\""), .cross("Nobody can confirm you were home at 1:10?", "\"I live alone, so no one can. I wish I'd had a camera or a roommate.\""), .cross("A key with paint flecks was found in your jacket, wasn't it?", "\"A deputy said a key had flecks on it. I carry keys in that pocket, and I can't explain how paint got on one.\""), .cross("You didn't call the manager about the parking?", "\"I did once, and it didn't help. That's why I left the note.\"")],
        openings: ("A week after {D} left a note on {V}'s windshield reading, Park elsewhere or else, {V}'s car was keyed down both sides overnight for $1,300 in damage. The lot camera shows a hooded figure walking the length of the car at 1:10 a.m.", "The camera shows a hood and no face, and {D} says {D.he} was asleep in bed. The defense says a parking note shows a grudge, not a crime, and the State has no proof of who held the key."),
        closings: ("A note that said or else, a keyed car, and a hooded figure at 1:10 a.m. {D} had the motive and the history, and the paint on the key in {D}'s jacket completes the picture.", "No face, no weapon on camera, no witness, and a jacket that does not fit {D}. A rude note is not a keyed car, and the State has not proved who did the damage."),
        timeline: [(-7, "{D} leaves the note."), (0, "1:10 a.m.: a hooded person walks the car."), (0, "7 a.m.: {V} finds the paint scratched.")],
        identified: "A lot camera and a note.",
        impact: "Seven days after a note.")

    static let patioShouting = SmallCases.make(
        key: "story.patioShouting",
        category: .publicOrder,
        headlines: ["Bar Patio Argument Spills Into Street, Deputy Called", "Patrons Say Man Shouted Threats at Passing Cars"],
        law: "disorderly",
        spec: "Disturbed the peace by loud and abusive language in a public place, on {DATE}.",
        ages: 19...55,
        victim: false,
        summary: "At 12:20 a.m. on {DATE}, {D} shouted at drivers from the edge of a bar patio. A deputy told {D} twice to go home. {D} kept shouting and stepped into the road. {DL} says {D.he} was celebrating a birthday and was not threatening anyone.",
        state: [E(.statement, 3, "Deputy", "{D} shouted at passing cars and stepped into the road after two warnings."), E(.video, 2, "Bar Camera", "{D} waves arms at the road.")],
        defense: [E(.statement, 1, "Birthday", "{DL} says it was a birthday celebration.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you see at 12:20 a.m.?", "\"I saw {D} at the edge of a bar patio shouting at cars passing on the road. The drivers were slowing down, and some looked unsure.\""), .direct("Did you warn {D}?", "\"Yes. I told {D} twice to go home. The second time I was close enough to speak in a normal voice.\""), .direct("What did {D} do after the warnings?", "\"{D} kept shouting and stepped into the road. I made the arrest right after that, for creating a disturbance.\""), .direct("How many people were on the patio at that hour?", "\"About twenty, a mix of customers and a few smokers. The music was loud and the patio was packed, and most of them were not near the road.\""), .direct("What exactly was {D} shouting?", "\"Mostly a stream of celebratory shouts and a few remarks at passing cars. At one point I heard {D} yell something at a driver, but I could not make out the words.\""), .direct("How did you handle the warnings?", "\"I walked over, introduced myself, and said it was past midnight and {D} needed to go home. I repeated it ten minutes later.\""), .cross("{D} says it was a birthday celebration, doesn't {D.he}?", "\"Yes, that was {D}'s explanation. It looked like a party, and people were in good moods around the patio.\""), .cross("Nobody was hurt, were they?", "\"No. No one was injured and no vehicle was struck.\""), .cross("Did you hear {D} threaten anybody?", "\"I heard shouting. I did not hear a specific threat to a particular person, and I would have to rely on my notes.\""), .cross("Did any driver complain to you about {D}?", "\"No. A couple of cars slowed, but no one stopped or called, and I don't know of any complaint.\""), .cross("Was {D} in the road long enough to interfere with traffic?", "\"No. It was a few seconds and a car had to brake a little, but no one was struck and no vehicle left the road.\"")],
        theory: ("{D} ignored two warnings and shouted into traffic.", "A noisy birthday."),
        allocution: "\"I'm sorry. I drank too much.\"",
        truths: ("{DL} told a driver 'I'll flip your car.'", "The 'drivers' were friends leaving the party."),
        defendant: [.direct("Were you shouting at cars?", "\"Yes, I was. I was celebrating a birthday and had a few drinks. I was being loud, and I was not trying to threaten anyone.\""), .direct("Why were you out near the road?", "\"The patio was crowded, and I stepped to the edge for some air. I was waving at the cars that passed.\""), .direct("Did you hear the deputy's warnings?", "\"Not both of them. It was loud on the patio, and I was caught up in the moment. I did not hear the first one.\""), .direct("Whose birthday was it, and how long had you been at the bar?", "\"Mine. I'd been there about five hours with friends, and we'd had dinner, played darts, and had drinks all evening.\""), .direct("What were you doing at the edge of the patio?", "\"Waving at friends who were leaving. I called out to a couple of them and joked with others on their way to their cars.\""), .direct("What happened when the deputy came over?", "\"I was polite, but I was still excited. I said I would go inside, and then I walked back toward the road to say goodbye to someone.\""), .cross("The deputy says you were told twice to go home. Is the deputy lying?", "\"I do not think the deputy lied. I just did not hear it clearly, and I should have paid better attention.\""), .cross("You stepped into the road, didn't you?", "\"Briefly. I did not realize how close I was to traffic, and I stepped back right away.\""), .cross("You were yelling at drivers who did not know you. How is that not a disturbance?", "\"It was noisy, I'll give you that. I was not angry. I was happy, and it came out loud.\""), .cross("You'd been drinking for five hours. Were you intoxicated?", "\"I'd had enough that I was loud and not thinking. I wasn't falling down, but I wasn't paying close attention either.\""), .cross("The deputy told you to go home twice. Why did you stay?", "\"I thought I was going to leave in a minute. I should have walked straight home, and I understand why the deputy was frustrated.\"")],
        openings: ("At 12:20 in the morning, {D} stood at the edge of a bar patio shouting at passing drivers. A deputy gave two warnings to go home, and {D} kept shouting and stepped into the road.", "This was a loud birthday celebration, not a threat. The defense will show a person who did not hear the warnings and meant no harm to any driver."),
        closings: ("Two warnings, ignored, and a person shouting at traffic who then stepped into a roadway at midnight. That is a public disturbance, and a birthday is not a defense.", "{D} was happy, loud, and had a few drinks, but never threatened or touched anyone. A noisy celebration is not a crime unless the State proves something more."),
        timeline: [(0, "12:20 a.m.: {DL} shouts from the patio."), (0, "12:30 a.m.: a deputy warns {DL} twice."), (0, "12:40 a.m.: {DL} steps into the road.")],
        identified: "A deputy's patrol.",
        mood: .indifferent,
        genders: ["D": .male])

    static let prankNineOneOne = SmallCases.make(
        key: "story.prankNineOneOne",
        category: .publicOrder,
        headlines: ["False Report of Armed Man Sends Deputies to Neighbor's House", "Anonymous 911 Call Traced to Teenager's Phone"],
        law: "falseReport",
        spec: "Willfully made a false report to law enforcement, on {DATE}.",
        ages: 18...30,
        victim: false,
        summary: "Dispatchers received a call on {DATE} saying a man with a gun was in a neighbor's yard. Four deputies surrounded the home. No one was armed. The call was traced to a prepaid phone bought by {D}. {DL} says {D.he} lost the phone the day before.",
        state: [E(.digital, 3, "Call Trace", "The call came from a prepaid phone registered to {D}."), E(.document, 2, "Dispatch Log", "Four deputies sent; no weapon found.")],
        defense: [E(.statement, 1, "Lost Phone", "{DL} says the phone was lost the day before.")],
        role: "911 dispatcher",
        exam: [.direct("What did the caller say on the line?", "\"The caller reported a person with a gun in a neighbor's yard. The voice sounded disguised, and the caller hung up quickly.\""), .direct("Where did the call come from?", "\"It traced to a prepaid phone. The store records showed that {D} bought that phone about a month earlier.\""), .direct("What was the response?", "\"Four deputies surrounded the home. They found no one armed and no gun, and the people inside were frightened.\""), .direct("How long did the call last?", "\"About ninety seconds. The caller spoke in a low, flat voice and gave an address and a description of a person in the back yard.\""), .direct("Was there anything unusual about the call?", "\"It came from a number that wasn't in our system, and the caller hung up before I could ask questions. That pattern is typical of a prank.\""), .direct("How did you trace the number?", "\"We pulled the carrier's records and matched the phone to a prepaid purchase at a store. The store's records had a name and a card number.\""), .cross("The caller's voice wasn't {D}'s, was it?", "\"I can't say it was. The voice was disguised, so I cannot say it was {D} or someone else.\""), .cross("{D} says the phone was lost, doesn't {D.he}?", "\"Yes. {D} said the phone had gone missing the day before, but I have no way to confirm when.\""), .cross("Did you check whether anyone else could have used the phone?", "\"That is for investigators. I only handled the call and the trace, and I cannot say who held the phone.\""), .cross("Did the store record the buyer's face?", "\"The store camera footage had been overwritten by the time we asked, so I can't say who bought the phone.\""), .cross("Have there been other prank calls from that phone before?", "\"Not that I found. The phone has only one call in its history, and it was the call to us.\"")],
        theory: ("{D} made a false call.", "A lost phone."),
        allocution: "\"It was supposed to be a joke.\"",
        truths: ("{DL}'s account shows a 'phone lost' report made after the call.", "A housemate admitted making the call from {DL}'s lost phone."),
        defendant: [.direct("Did you make that call?", "\"No. I did not call 911 and I did not report a gun. I would never do that to the neighbors or to deputies.\""), .direct("Where was your prepaid phone that day?", "\"I lost it the day before. I looked everywhere and never found it, and I did not know anyone had used it.\""), .direct("Why did you buy a prepaid phone?", "\"I wanted a cheap phone for a short time. I bought it last month, and I did not think much about it.\""), .direct("Describe the phone in your own words.", "\"I bought it for a few weeks while my regular phone was being repaired. It was a cheap prepaid phone and I kept it in my jacket.\""), .direct("When did you realize it was missing?", "\"The morning before the call. I checked my jacket pockets, my car, and the apartment, and I never found it.\""), .direct("Did you report it lost?", "\"I meant to, but I didn't get to it until after I heard what happened. I felt silly reporting a cheap phone.\""), .cross("The phone is yours, bought by you, and used for the call, isn't it?", "\"It was mine, but I had lost it. I can't say who picked it up, but I did not make that call.\""), .cross("You had a dispute with that neighbor, didn't you?", "\"We argued about a fence. It was not a big fight. It was a normal disagreement, and I did not hold a grudge.\""), .cross("Did you report the phone lost to anyone?", "\"Not right away. I figured it would turn up, and I did not think I needed to tell anyone.\""), .cross("You and the neighbor argued about a fence. Wouldn't a prank call be a natural way to get back at them?", "\"I was upset, but I would never call 911 and say someone had a gun. I know how serious that is.\""), .cross("Your phone was used within a day of losing it. What's the chance a stranger found it and called?", "\"It's low, but it's not impossible. I live in an apartment complex and the phone could have been picked up by someone who knew who owned it.\"")],
        openings: ("Dispatchers took a call reporting a person with a gun in a neighbor's yard. Four deputies surrounded the home, and no one was armed. The call traced to a prepaid phone bought by {D}.", "{D} lost that phone the day before the call. The defense will show that the caller's voice was disguised and that nothing proves {D} was the one on the line."),
        closings: ("A false report of a gun, four deputies at a home, and a phone traced to {D}. A neighbor feud and a purchased phone point in one direction.", "A lost phone can be picked up by anybody. The voice was disguised and no one identified {D}. A phone's owner is not the same as the caller."),
        timeline: [(-2, "{DL} argues with the neighbor."), (0, "The call is made from the prepaid phone."), (0, "Four deputies surround the neighbor's home.")],
        identified: "A call trace.",
        mood: .wantsConviction,
        impact: "They had guns drawn on my kids.")

    static let porchPackages = SmallCases.make(
        key: "story.porchPackages",
        category: .property,
        headlines: ["Delivery Packages Vanish From Porches on Maple Street", "Doorbell Cameras Show Same Sedan at Each Stolen Package"],
        law: "misdLarceny",
        spec: "Stole packages valued at $380 belonging to {V}, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "Three packages left on {V}'s porch on {DATE} were gone by noon. A doorbell camera showed a gray sedan stop, a man take the boxes, and drive away. The plate belonged to {D}. {DL} says a friend borrowed the sedan.",
        state: [E(.video, 3, "Doorbell Camera", "A man takes three boxes and leaves in a gray sedan."), E(.document, 3, "Registration", "The sedan is registered to {D}.")],
        defense: [E(.statement, 1, "Friend Borrowed", "{DL} says a friend borrowed the sedan.")],
        role: "Homeowner",
        exam: [.direct("What was taken from your porch?", "\"Three packages worth about $380 in total. They had been delivered that morning and were gone by noon.\""), .direct("What does your doorbell camera show?", "\"A gray sedan stops at the curb, and someone gets out, picks up the three boxes, and drives away.\""), .direct("How did {D} come into this?", "\"The plate on the sedan belongs to {D}. A deputy traced it and came to speak with {D}.\""), .direct("How do you usually receive packages, and when did these arrive?", "\"They're delivered to the porch. A courier left three boxes at about nine that morning, and I got the delivery notice on my phone.\""), .direct("What was in the packages?", "\"A pair of boots, a set of cookware, and a gift for a relative. Together they were worth about $380.\""), .direct("What did you do when you found the porch empty?", "\"I checked the doorbell camera, called the sheriff's office, and sent the video. The deputy told me the plate was traceable.\""), .cross("The face is not clear on the video, is it?", "\"No. The camera angle is poor, and I cannot say who the person is. I can describe the car better than the face.\""), .cross("A car can be borrowed by someone else, can't it?", "\"Of course. I cannot say who was driving. I can only say the plate on the sedan belongs to {D}.\""), .cross("Did you see anything else that connects {D} to your boxes?", "\"No. All I have is the camera and what deputies told me.\""), .cross("Did you recognize the person on the camera?", "\"No. I don't know anyone who drives that car, and the person's face is hidden by a hat.\""), .cross("Did the courier's delivery record confirm the boxes were left at your porch?", "\"Yes. The courier's photo shows them on the mat at 9:04, and nothing after that shows who took them.\"")],
        theory: ("{D} took packages from a porch.", "A friend's trip in {D.his} car."),
        allocution: "\"I took the packages. I'm sorry.\"",
        truths: ("Two of the stolen boxes were found in {DL}'s garage.", "The friend who borrowed the sedan had a key and admitted taking the boxes."),
        defendant: [.direct("Did you take packages from {V}'s porch?", "\"No. I did not take them, and I was not there. I have never been to that house.\""), .direct("Who was using your gray sedan?", "\"A friend had borrowed the car that day. I loaned it to {D.him} for a few hours, and I did not ask where {D.he} was going.\""), .direct("Why would boxes be found in your garage?", "\"Boxes were delivered by mistake to my address. I did not know whose they were, and I did not open them.\""), .direct("Tell the jury where you were between 10 and 12 that morning.", "\"At home for most of it. I did some laundry and watched a show, and I left for an appointment just before noon.\""), .direct("What can you tell us about your sedan?", "\"A gray sedan I've owned for four years. I keep the keys on a hook by the door and sometimes friends borrow it.\""), .direct("How did the boxes end up in your garage?", "\"Two packages arrived at my address by mistake a few days before. I put them in the garage meaning to return them, and never got to it.\""), .cross("The plate on that car is yours, isn't it?", "\"Yes, the sedan is mine. I'm not denying that. I just was not the one driving it.\""), .cross("Can you name the friend?", "\"Yes, I can give a name, but I do not have an address. I know it is hard to believe.\""), .cross("Boxes of someone else's packages in your garage. How is that a mistake?", "\"It looks bad, I know. They were left at my door, and I put them in the garage until I could sort it out.\""), .cross("Two stolen boxes were found in your garage. Is that a coincidence?", "\"They weren't stolen by me. Boxes had come to my address by mistake and I didn't see the names on them until a deputy pointed them out.\""), .cross("You say a friend borrowed the sedan. Why didn't the friend come forward?", "\"I don't know. I've asked, and I can't explain why the friend hasn't helped.\"")],
        openings: ("Three packages worth $380 vanished from {V}'s porch. A doorbell camera shows a gray sedan and a person taking the boxes, and the plate on that sedan belongs to {D}.", "Jurors will also see a video with no clear face and a car that was lent to a friend. A license plate shows ownership, not who was behind the wheel."),
        closings: ("The camera shows the sedan, the plate leads to {D}, and packages were gone within hours. The car is {D}'s, and the plate does not lie.", "No one can see a face, and a friend had the car. The State has proven who owns the sedan, not who took the boxes."),
        timeline: [(0, "9 a.m.: packages are delivered."), (0, "10:15 a.m.: a gray sedan stops at the porch."), (0, "12 p.m.: {V} finds the porch empty.")],
        identified: "A doorbell camera and a plate.",
        impact: "One was a gift for my daughter.",
        genders: ["D": .male])

    static let contractorTools = SmallCases.make(
        key: "story.contractorTools",
        category: .property,
        headlines: ["$7,000 in Tools Stolen From Contractor's Locked Truck", "Pawn Shop Records Lead Detective to Defendant"],
        law: "felonyLarceny",
        threshold: 6,
        spec: "Stole tools valued at $7,000 belonging to {V}, on {DATE}.",
        ages: 19...50,
        victim: true,
