        defenseExam: [.direct("What do you do at the pawn shop?", "\"I'm a clerk. I take in merchandise, check IDs, log serial numbers, and issue tickets for every item.\""), .direct("What happened when {D} came in?", "\"{D} brought in a saw and asked for a loan. I logged {D}'s license and the saw's serial number and wrote the ticket.\""), .direct("Did {D} try to hide the initials?", "\"No. They were plainly visible on the saw's housing. {D} didn't cover or scratch them.\""), .direct("How did {D} act?", "\"Calm and ordinary. {D} didn't rush or act nervous and answered each question I asked.\""), .direct("Did {D} say where the saw came from?", "\"{D} said it came from a flea market. I don't remember a vendor's name being mentioned.\""), .direct("What happens if a customer brings in stolen goods?", "\"They're flagged against police reports. Most customers don't come in with stolen goods, and I assume a customer is honest until I see a flag.\""), .cross("You don't know where {D} got the saw, do you?", "\"No. I only know what {D} told me, and I can't verify it.\""), .cross("Isn't it true thieves sometimes use their real ID?", "\"It happens, but not often. I wouldn't read anything into it either way.\""), .cross("How long between the break-in and the pawn?", "\"The ticket was three days after the break-in, as the detective told me.\""), .cross("Did {D} ask for more than the saw's worth?", "\"No. {D} took the loan offer without haggling.\""), .cross("You didn't see {D} take the tools from the truck?", "\"No. I wasn't anywhere near that, and I only saw {D} at my counter.\"")],
